const input = $input.first().json;
const result = input.output ?? input;

return [{
  json: {
    success: true,
    feature_id: 'F-04',

    customer_id: result.customer_id ?? null,
    analysis_id: result.analysis_id ?? null,

    recommendations: Array.isArray(result.recommendations)
      ? result.recommendations.map(item => ({
          recommendation_rank: item.recommendation_rank ?? null,

          product_id: item.product_id ?? null,
          device_name: item.device_name ?? null,

          plan_id: item.plan_id ?? null,
          plan_name: item.plan_name ?? null,

          expected_benefit: item.expected_benefit ?? null,
          benefit_info: item.benefit_info ?? null,
          eligibility_condition: item.eligibility_condition ?? null,
          recommendation_reason: item.recommendation_reason ?? null
        }))
      : [],

    information_status: result.information_status ?? 'insufficient',

    missing_information: Array.isArray(result.missing_information)
      ? result.missing_information
      : []
  }
}];

const base = $('상품·요금제 기준정보 준비').first().json;
const devices = $('기종 정보 조회').all().map((item) => item.json).filter((d) => d.device_id);
const plans = $('요금제 정보 조회').all().map((item) => item.json).filter((p) => p.plan_id);

return [{
  json: {
    ...base,
    product_catalog: {
      products: devices.map((d) => ({
        product_id: d.device_id,
        product_name: d.device_name,
        brand: d.manufacturer,
        device_price: d.device_price,
      })),
      plans: plans.map((p) => ({
        plan_id: p.plan_id,
        plan_name: p.plan_name,
        monthly_fee: p.monthly_fee,
        allowance_info: p.allowance_info,
      })),
    },
  },
}];
